#include <bits/stdc++.h>
#define inline_func inline
#define reg register
#define long_long long long
#define MAXN (250005)

using namespace std;

int f[MAXN][18], c[18], ans[18], lg, m, n, k, rhl;
int fac[MAXN], ifac[MAXN], inv[MAXN], cnt[MAXN], v[MAXN];

inline_func array_add(int *dest, int *src, int mode) {
  for (reg int i=0; i<lg; ++i) {
    dest[i] += mode ? src[i] : (rhl - src[i]);
    if (dest[i] >= rhl) dest[i] -= rhl;
  }
}

inline_func array_multiply(int *a, int *b) {
  memset(c, 0, sizeof(c));
  for (reg int i=0; i<lg; ++i) {
    if (a[i] == 0) continue;
    for (reg int j=0; i + j < lg; ++j)
      c[i + j] = (1LL * a[i] * b[j] + c[i + j]) % rhl;
  }
  memcpy(a, c, sizeof(c));
}

inline_func array_power(int *a, reg int b) {
  memset(ans, 0, sizeof(ans));
  ans[0] = 1;
  while (b) {
    if (b & 1) array_multiply(ans, a);
    if (b >>= 1) array_multiply(a, a);
  }
  memcpy(a, ans, sizeof(ans));
}

inline_func mod_pow(reg int base, reg int exp) {
  reg int res=1;
  while (exp) {
    if (exp & 1) res=1LL*res*base%rhl;
    if (exp>>=1) base=1LL*base*base%rhl;
  }
  return res;
}

int main() {
#ifndef ONLINE_JUDGE
  freopen("game.in", "r", stdin);
  freopen("game.out", "w", stdout);
#endif
  cin >> n >> k >> rhl;
  if (n & 1) {
    cout << mod_pow(k, n) << "\n";
    return 0;
  }
  fac[0]=ifac[0]=f[0][0]=1;
  for (m=1; m<=n; m<<=1) ++lg;
  for (reg int i=1; i<=n; ++i) {
    inv[i] = (i==1) ? 1 : (1LL*(rhl - rhl/i)*inv[rhl%i]%rhl);
    fac[i] = (1LL*fac[i-1]*i)%rhl;
    ifac[i] = (1LL*ifac[i-1]*inv[i])%rhl;
    cnt[i] = cnt[i>>1] + (i&1);
    f[i][cnt[i]] = ifac[i];
  }
  v[n] = 1;
  for (reg int i=n; i; --i) {
    if (!v[i]) continue;
    for (reg int j=i; j; (j &= i)) v[j] = 1;
  }
  for (reg int i=1; i<m; i<<=1)
    for (reg int j=0; j<=n; ++j) if (j & i) array_add(f[j], f[j^i], 1);
  for (reg int i=0; i<=n; ++i) if (v[i]) array_power(f[i], k);
  for (reg int i=1; i<m; i<<=1)
    for (reg int j=0; j<=n; ++j) if (j & i) array_add(f[j], f[j^i], 0);
  cout << (mod_pow(k, n) - 1LL * f[n][cnt[n]] * fac[n] % rhl + rhl) % rhl;
  return 0;
}
